from solution import ncr_modp


def test_issue_example():
    """Check example assert ncr_modp(10,2,13)==6."""
    assert ncr_modp(10, 2, 13) == 6  # C(10,2)=45, 45=3*13+6


def test_issue_r_zero():
    """Check nCr%p with r=0 equals 1%p."""
    assert ncr_modp(7, 0, 5) == 1  # C(7,0)=1, 1=0*5+1


def test_issue_r_equals_n():
    """Check nCr%p with r=n equals 1%p."""
    assert ncr_modp(5, 5, 7) == 1  # C(5,5)=1, 1=0*7+1


def test_issue_r_one():
    """Check nCr%p with r=1 equals n%p."""
    assert ncr_modp(7, 1, 5) == 2  # C(7,1)=7, 7=1*5+2


def test_issue_n_zero():
    """Check nCr%p with n=0 and r=0 equals 1%p."""
    assert ncr_modp(0, 0, 5) == 1  # C(0,0)=1, 1=0*5+1


def test_issue_r_greater_than_n():
    """Check nCr%p with r>n equals 0."""
    assert ncr_modp(3, 5, 7) == 0  # no choice, defined as 0, 0=0*7+0


def test_issue_small_values():
    """Check nCr%p for small n=5 r=2 p=7."""
    assert ncr_modp(5, 2, 7) == 3  # C(5,2)=10, 10=1*7+3


def test_issue_n_ge_p():
    """Check nCr%p when n>=p for prime p."""
    assert ncr_modp(5, 2, 3) == 1  # C(5,2)=10, 10=3*3+1


def test_issue_composite_modulus():
    """Check nCr%p for composite modulus p=4."""
    assert ncr_modp(5, 2, 4) == 2  # C(5,2)=10, 10=2*4+2


def test_issue_larger_n():
    """Check nCr%p for larger n=10 r=3 p=7."""
    assert ncr_modp(10, 3, 7) == 1  # C(10,3)=120, 120=17*7+1


def test_issue_mod_two():
    """Check nCr%p for smallest prime modulus p=2."""
    assert ncr_modp(4, 2, 2) == 0  # C(4,2)=6, 6=3*2+0


def test_contract_mod_one():
    """Check nCr%p with p=1 is always 0."""
    assert ncr_modp(5, 2, 1) == 0  # C(5,2)=10, 10=10*1+0


def test_contract_result_in_range():
    """Check nCr%p lies in range 0 <= result < p."""
    assert 0 <= ncr_modp(6, 2, 5) < 5  # C(6,2)=15, 15=3*5+0 so 0 in [0,5)


def test_contract_returns_int():
    """Check ncr_modp returns the value of nCr%p as int."""
    assert isinstance(ncr_modp(10, 2, 13), int)  # C(10,2)=45, 45=3*13+6 so int 6
